import { baseLanguages } from '~i18n/languages'

// Generated by `pnpm og:generate` (scripts/og); one card per locale, English for anything else.
export const OPEN_GRAPH_IMAGE_WIDTH = 1200
export const OPEN_GRAPH_IMAGE_HEIGHT = 630
const fallbackLanguage = 'en'

export const getOpenGraphImagePath = (language?: string) => {
  const lang = language && language in baseLanguages ? language : fallbackLanguage
  return `/assets/og/${lang}.png`
}
